def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        choices = []
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])]
            choices.append([-1] + versions)

        best_vector = None
        best_versions = None
        for values in product(*choices):
            selected = {name: version for name, version in zip(names, values) if version != -1}
            if any(name not in selected or not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            if any(name in selected and selected[name] != version
                   for name, version in pins.items()):
                continue

            graph = {}
            valid = True
            for name, version in selected.items():
                row = next(row for row in packages[name] if row["version"] == version)
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    dep_version = selected.get(dep_name, -1)
                    if dep_version == -1 or not dep["min"] <= dep_version <= dep["max"]:
                        valid = False
                        break
                    deps.append(dep_name)
                graph[name] = deps
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            active = set()
            finished = set()
            cyclic = False

            def visit(name):
                nonlocal cyclic
                reachable.add(name)
                if name in active:
                    cyclic = True
                    return
                if name in finished:
                    return
                active.add(name)
                for other in graph.get(name, []):
                    visit(other)
                active.remove(name)
                finished.add(name)

            for name in roots:
                visit(name)
            if cyclic or reachable != set(selected):
                continue
            vector = tuple(values)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = selected

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        options = [job for job in jobs if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for subset in combinations(options, k):
            ids = [job["id"] for job in subset]
            id_set = set(ids)
            if not mandatory.issubset(id_set):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            value = sum(job["value"] for job in subset)
            chosen_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and chosen_ids < best_ids)):
                best_value = value
                best_ids = chosen_ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


